def safe_join(base, user_path):
    import os

    if not base.endswith(os.path.sep):
        base += os.path.sep

    user_path = os.path.normpath(user_path)

    if user_path.startswith(os.path.sep):
        raise ValueError("Absolute paths are not allowed")

    if user_path == '.' or user_path == '':
        return base

    if user_path.startswith('..'):
        raise ValueError("Parent directory traversal is not allowed")

    joined_path = base + user_path

    if joined_path.startswith(base) and not joined_path.endswith(os.path.sep):
        return joined_path

    raise ValueError("The resulting path is not within the base directory")
